'use strict';
// DEMO route gate. Real accounts require server-side authentication and authorization.
(()=>{const staff=document.documentElement.dataset.portal==='staff',key=staff?'staff':'client';window.PORTAL_ROLE=staff?'admin':'client';try{let session=sessionStorage.getItem('ecocharge-entry:'+key);if(!staff&&!session&&new URL(location).searchParams.get('guest')==='1'){session=JSON.stringify({role:'client',guest:true,at:Date.now()});sessionStorage.setItem('ecocharge-entry:client',session);} if(!staff&&!session&&new URL(location).searchParams.get('preview')==='1'&&sessionStorage.getItem('ecocharge-entry:staff')){session='staff-preview';sessionStorage.setItem('ecocharge-entry:client',JSON.stringify({role:'client',preview:true,at:Date.now()}))}if(!session)location.replace(new URL((staff?'team/':'login/')+'?next='+encodeURIComponent(new URL(location).searchParams.get('tab')||''),document.baseURI))}catch{location.replace(new URL(staff?'team/':'login/',document.baseURI))}})();
